  _ = `Actualizarea nu a reușit. Încearcă din nou mai târziu.`,
  _ = `Difuzarea a fost oprită cu succes`,
  _ = `Difuzarea nu a putut fi oprită, așa că încearcă din nou`,
  _ = `Oprește difuzarea`,
  _ = `Despre acest joc`,
  _ = `Pagina de magazin`,
  _ = `Raportează difuzarea`,
  _ = `Raportează această difuzare`,
  _ = `Întrebări frecvente despre difuzări`,
  _ = `Vezi întrebările frecvente despre difuzare`,
  _ = `Trimite feedback`,
  _ = `Raportează această difuzare`,
  _ = `Te rugăm să descrii modul în care sunt încălcate condițiile de utilizare a platformei Steam de către acest element. Te rugăm să incluzi orice informații sau linkuri relevante. Trimiterea acestei raportări este ireversibilă.`,
  _ = `Program`,
  _ = `Instrument pentru programări`,
  _ = `Creezi un program care să apară pe pagina ta de evenimente?`,
  _ = `Adaugă o înregistrare în program`,
  _ = `Elimină această înregistrare`,
  _ = `Previzualizare a programului încorporat`,
  _ = `Legenda tipurilor de programări`,
  _ = `Tip`,
  _ = `Scop`,
  _ = `Meci între adversari`,
  _ = `Acesta este un meci competitiv între două sau mai multe persoane sau echipe. După terminarea meciului, poți actualiza rezultatele și poți include informațiile despre câștigător.`,
  _ = `Difuzare`,
  _ = `Acest tip de acțiune îndeamnă utilizatorii să urmărească o transmisiune în direct pe Steam sau altundeva în această perioadă.`,
  _ = `Pornește jocul`,
  _ = `Acest tip de acțiune îi îndeamnă pe jucători să pornească jocul și să-l joace la momentul specificat pentru a se alătura evenimentului.`,
  _ = `În viața reală`,
  _ = `Acest tip de eveniment este utilizat atunci când o parte din program va fi dedicată doar persoanelor prezente fizic la eveniment și nu poate fi transmis în direct. Notă: ar putea fi ideal să nu incluzi acest tip de eveniment în program, deoarece fanii tăi de pe Steam nu pot participa.`,
  _ = `Momentul de început`,
  _ = `Exprimată în minute de la începere evenimentului`,
  _ = `Minute`,
  _ = `Această înregistrare din program a fost modificată față de cea implicită. Sigur dorești să o ștergi? Această acțiune este ireversibilă.`,
  _ = `Circuite actuale`,
  _ = `Un circuit asociază o serie de evenimente corelate cu o imagine de marcă și o schemă de culori comune. Nu este obligatoriu ca evenimentele să apară în program. De exemplu, scena principală sau circuitul artistic.`,
  _ = `Niciun circuit definit.`,
  _ = `Adaugă un circuit`,
  _ = `Adaugă în program un circuit nou evenimentelor de grup și de marcă.`,
  _ = `Șterge circuitul`,
  _ = `Sigur dorești să ștergi acest circuit?`,
  _ = `Circuit nemarcat: %1$s`,
  _ = `Adaugă evenimente special pentru această serie. Acestea sunt valabile numai dacă sunt publicate, încep și se termină în intervalul de timp prevăzut și corespund categoriei de evenimente permise pentru program.`,
  _ = `Acorduri privind evenimentul de reduceri`,
  _ = `Pentru a putea utiliza instrumentele de editare a reducerilor, va trebui să fii de acord cu următoarele cerințe:`,
  _ = `Înțeleg că pagina de reduceri trebuie să precizeze în mod clar grupul sau persoanele responsabile de organizarea campaniei de reduceri sau evenimentului.`,
  _ = `Înțeleg că nu pot garanta participanților un anumit nivel de vizibilitate pe Steam și că nu pot percepe taxe pentru plasarea în pagină.`,
  _ = `Înțeleg că Valve își rezervă dreptul de a modifica o pagină de reduceri, inclusiv, dar fără a se limita la vizibilitatea jocurilor sau difuzărilor pe pagină, textul sau imaginile care descriu evenimentul.`,
  _ = `Înțeleg că Valve decide ce evenimente dorește să promoveze în cadrul magazinului Steam și că evenimentul meu poate să nu fie evidențiat.`,
  _ = `Înțeleg că pot adăuga pe pagina promoțională doar jocuri pentru care am primit permisiune din partea dezvoltatorilor sau editorilor. Dezvoltatorii unui joc vor vedea că jocul lor este inclus în promoția mea imediat ce-l voi adăuga pe pagina mea.`,
  _ = `Sunt de acord cu toate regulile menționate în documentația %1$s.`,
  _ = `Consultă %1$s pentru a afla mai multe detalii cu privire la designul și crearea unei pagini de reduceri.`,
  _ = `documentația`,
  _ = `Persoana de contact`,
  _ = `Dacă dezvoltatorii de jocuri, editorii sau presa au întrebări cu privire la acest eveniment, pe cine ar trebui să contacteze?`,
  _ = `introdu numele`,
  _ = `introdu adresa de e-mail`,
  _ = `Verifică regulile și informațiile de contact`,
  _ = `Ai citit și acceptat regulile la data de %1$s.`,
  _ = `Promoții găzduite de editori sau dezvoltatori`,
  _ = `Promoții pentru serii`,
  _ = `Pagini de prezentare pentru festivaluri/convenții`,
  _ = `Promoții regionale`,
  _ = `Promoții tematice`,
  _ = `Ai citit și acceptat regulile.`,
  _ = `Te rugăm să furnizezi numele și URL-ul organizatorului acestui eveniment. Aceste informații sunt necesare, pot fi editate în orice moment și vor fi afișate în partea de sus a paginii tale de reduceri.`,
  _ = `Organizatorii evenimentului`,
  _ = `Modifică organizatorii evenimentului`,
  _ = `Introdu informațiile organizatorului`,
  _ = `Te rugăm să introduci numele entității care a organizat acest eveniment. Linkul poate fi către pagina de creator de pe Steam a organizatorului sau poate fi către un URL extern. Numele din engleză este obligatoriu, dar localizarea numelui este opțională.`,
  _ = `Aceste informații vor fi afișate pe pagina ta de reduceri în felul următor:`,
  _ = `Adaugă un organizator`,
  _ = `Numele organizatorului`,
  _ = `URL-ul`,
  _ = `Grupul de imagini localizate`,
  _ = `Imaginea principală pentru grupul de imagini localizate`,
  _ = `Aceasta este imaginea implicită dacă nu există o versiune localizată pentru o limbă pe care un utilizator încearcă să o vizualizeze. Ar putea fi o imagine fără text sau într-o limbă vorbită de către clienții tăi.`,
  _ = `Dacă imaginea ta conține text, poți încărca aici versiunile localizate ale imaginii tale pentru orice limbă acceptată de Steam. Steam va afișa automat imaginile localizate corespunzătoare clienților.`,
  _ = `Încarcă imagini al căror nume se termină cu %1$s pe Steam pentru a le atribui automat limba corespunzătoare.`,
  _ = `limbajul API WEB`,
  _ = `Imagini`,
  _ = `Utilizează spațiul de jos pentru a încărca imagini noi care să fie accesibile pentru oricare dintre evenimentele tale. Poți trage și elibera fișierele din această secțiune sau poți apăsa clic pentru a insera imaginile în postarea ta, fie la dimensiune completă, fie ca miniatură.`,
