  _ = `Sigur dorești să ștergi %1$s?`,
  _ = `Avertisment: Evenimentele sau anunțurile vechi care fac referință la imaginea aceasta nu vor mai funcționa.`,
  _ = `Nicio imagine`,
  _ = `Nu coincide cu nicio imagine`,
  _ = `Eroare la încărcarea imaginii: „%1$s”`,
  _ = `Trage imaginile aici pentru a le încărca (maxim 5 MB)`,
  _ = `Sau răsfoiește`,
  _ = `Sau alege din`,
