  _ = `Dublu clic pentru a selecta imaginea`,
  _ = `Se încarcă imaginile`,
  _ = `Se încarcă %1$s din %2$s imagini. Te rugăm să aștepți.`,
  _ = `A fost întâmpinată o eroare la încărcarea imaginii „%1$s”, având codul de eroare „%2$s” și mesajul: „%3$s”`,
  _ = `Utilizatorul a solicitat anularea încărcării imaginii`,
  _ = `Succes! Toate imaginile au fost încărcate`,
  _ = `Se verifică ilustrația`,
  _ = `Se verifică tipul și dimensiunile suportate pentru fișierul cu ilustrația principală: „%1$s”`,
  _ = `Verificarea a eșuat: dimensiunea este incorectă pentru folosirea ca ilustrație principală.

Lățimea necesară este de cel puțin %1$s, iar imaginea are o lățime de %2$s.
Înălțimea redimensionată necesară este de %3$s, iar imaginea are o înălțime redimensionată de %4$s. Am modificat imaginea astfel încât lățimea să fie %5$s.`,
