  _ = `Dimensiune incorectă`,
  _ = `Apasă mai jos pentru a decupa și redimensiona imaginea la %1$s x %2$s.`,
  _ = `Imaginea pe care ai selectat-o este prea mică pentru acest tip de imagine. Imaginea trebuie să aibă o dimensiune cel puțin egală cu %1$s x %2$s.`,
  _ = `Editează imaginea bannerului`,
  _ = `Decupează imaginea`,
