  _ = `Secțiune de referință`,
  _ = `Imagine de titlu/antet`,
  _ = `Tip de secțiune promoțională necunoscut`,
  _ = `Această secțiune conține doar o imagine. Dorești să <1>convertești</1> secțiunea într-una de tip imagine titlu?`,
  _ = `Secțiunile de tip imagine facilitează localizarea imaginilor și sunt redate mai repede pe pagina promoțională finală care este afișată clienților. De asemenea, imaginile utilizate în antetul titlului nu afectează selectorul de imagini.`,
  _ = `Previzualizarea conținutului distribuit pe rețelele de socializare`,
  _ = `Aceasta este o previzualizare a conținutului care va fi afișat atunci când evenimentul este asociat sau distribuit pe rețelele de socializare.`,
