  _ = `Conținutul implicit pentru rețelele de socializare a fost suprascris de conținutul indicat în secțiunea de reduceri „Editor pentru distribuirea pe rețelele de socializare”.`,
  _ = `Opțional: asociază conturile de pe rețelele de socializare cu evenimentul și pagina principală. Acestea vor fi afișate într-un mod standard pentru toți clienții.`,
