  _ = `Elimină toate articolele din lista de mai sus`,
  _ = `Editează datele brute`,
  _ = `Această funcție permite editarea listei cu articolele conexe. Poate fi folosită pentru importul sau exportul din aplicații precum Excel, sau pentru efectuarea rapidă a unor modificări ample a listei de articole.`,
  _ = `Marcaje personalizate`,
  _ = `Permite editarea directă a listei de articole conexe pentru această campanie promoțională, alături de importul și exportul colecției personalizate de marcaje aplicate articolelor participante la promoție. Această opțiune este utilizată în special pentru importul unei selecții de marcaje personalizate care sunt gestionate cu ajutorul unei foi de calcul externe, fără a modifica celelalte marcaje ale articolelor. În plus, un subset de marcaje poate fi importat prin intermediul acestei ferestre de dialog, deoarece nu va elimina articolele care nu sunt listate.`,
  _ = `Importă din pagina de înscriere`,
  _ = `Deschide o fereastră de dialog care va permite importul tuturor aplicațiilor dintr-o pagină de înscriere și includerea în lista cu articole conexe.`,
  _ = `Sincronizarea articolelor`,
  _ = `Sincronizează marcajele demourilor`,
  _ = `Această funcție va parcurge toate articolele conexe, adăugând marcajul „HasDemo” (are demo) tuturor aplicațiilor cu demo și eliminându-l de la orice aplicație fără demo.`,
  _ = `Sincronizează`,
  _ = `Această opțiune permite sincronizarea diferitelor marcaje și a altor informații între articolele conexe și alte surse.`,
  _ = `Se sincronizează marcajele demourilor`,
  _ = `Editează marcajele automate`,
  _ = `Introdu numele marcajului`,
  _ = `Acesta este numele marcajului care va fi aplicat tuturor articolelor conexe care corespund cu filtrul asociat.`,
  _ = `Editează filtrul pentru articole (%1$s filtre)`,
  _ = `Editează filtrul pentru articole (%1$s filtre) (%2$s articole eliminate de filtru)`,
  _ = `Permite configurarea unui filtru care se va aplica tuturor articolelor conexe înainte de a lua în considerare secțiunile. Acest filtru se poate folosi, de exemplu, pentru excluderea tuturor titlurilor care nu au un demo sau care au un marcaj anume.`,
  _ = `Explorează`,
  _ = `Permite utilizarea instrumentului de filtrare pentru a examina articolele conexe configurate în prezent, în vederea determinării numărului celor care corespund criteriilor de filtrare sau care au marcaje asociate.`,
  _ = `Editare în grup`,
  _ = `Permite editarea în loturi a articolelor conexe. După furnizarea unei liste de articole, acestora li se pot asocia sau elimina marcaje în grup.`,
  _ = `Marcaje automate`,
  _ = `Permite crearea de marcaje automate: este vorba de un filtru care va aplica marcajul respectiv tuturor articolelor conexe corespunzătoare.`,
  _ = `Afișarea articolelor`,
  _ = `Afișează articolele (exclude-le pe cele filtrate)`,
  _ = `Afișează toate articolele`,
  _ = `Afișează articolele eliminate de filtru`,
  _ = `Importă pagina de înscriere`,
  _ = `Numele de înscriere`,
  _ = `Acesta este numele unei promoții la care s-a făcut referire în pagina de înscriere pentru a ști care este campania de reduceri din care trebuie să se fie importate datele.`,
  _ = `Prefixul marcajului`,
  _ = `Un prefix care se atașează marcajelor oferite de pagina de înscriere. Acesta permite separarea acțiunii specificate în pagina de înscriere de acțiunea din pagina de magazin`,
  _ = `Necesită un demo`,
  _ = `Dacă este bifată această căsuță, vor fi permise doar aplicațiile cu un demo asociat.`,
  _ = `Se încarcă aplicațiile de pe pagina de înregistrare`,
  _ = `Încarcă definițiile magazinului pentru a filtra aplicațiile care nu au o pagină de magazin`,
  _ = `Se încarcă etichetele din magazin pentru %1$s aplicații`,
  _ = `Se încarcă caracteristicile pentru %1$s aplicații`,
