  _ = `Se încarcă etichetele de magazin pentru %1$s aplicații`,
  _ = `Permite editarea avansată în format text a listei de articole pentru această capsulă, ceea ce facilitează importarea sau exportarea în loturi din cadrul instrumentelor externe.`,
  _ = `Editează articolele din secțiune`,
  _ = `Specifică articolele și ordinea în care dorești ca acestea să apară.`,
  _ = `Fiecare articol începe cu un ID și este urmat de un tip (opțional) și de o zi (opțional).`,
