  _ = `(Doar pentru Valve) Căutare fațetată`,
  _ = `Permite utilizatorilor să filtreze și să caute articole în aceasta secțiune. NOTĂ: activarea acestei opțiuni va elimina din această secțiune toate articolele evidențiate.`,
  _ = `Nume`,
